function process(objIn) {
  const points = Array.isArray(objIn) ? objIn : objIn.keypoints;
  if (!Array.isArray(points)) throw new Error('Expected an array or a keypoints array');
  if (points.length === 0) return { count: 0, mean: null, boundingBox: null };
  let sumU = 0, sumV = 0;
  let minU = Infinity, minV = Infinity, maxU = -Infinity, maxV = -Infinity;
  for (const point of points) {
    if (!point || !Number.isFinite(point.u) || !Number.isFinite(point.v)) {
      throw new Error('Each point must have finite numeric u and v values');
    }
    sumU += point.u; sumV += point.v;
    minU = Math.min(minU, point.u); minV = Math.min(minV, point.v);
    maxU = Math.max(maxU, point.u); maxV = Math.max(maxV, point.v);
  }
  return {
    count: points.length,
    mean: { u: sumU / points.length, v: sumV / points.length },
    boundingBox: { minU, minV, maxU, maxV, width: maxU - minU, height: maxV - minV }
  };
}
